package com.login.demo.config;
import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain security(HttpSecurity http) throws Exception { return http.csrf(csrf->csrf.ignoringRequestMatchers("/api/**")).authorizeHttpRequests(auth->auth.requestMatchers("/","/login","/registro","/css/**","/js/**","/api/**").permitAll().anyRequest().permitAll()).formLogin(form->form.loginPage("/login").permitAll()).logout(logout->logout.logoutSuccessUrl("/login?logout")).build(); } }
